export type AiState =
/**  Describing is turned off in Settings. */
"off" |
/**  Nothing waits to be described (or waits for OCR first). */
"idle" |
/**  A capture is being described. */
"working" |
/**
 *  The provider failed; waiting captures are described once it is
 *  retried.
 */
"error";

/**  What the queue is doing. Mirrors `AiStatus` in src/library/api.ts. */
export type AiStatus = AiStatus_Serialize | AiStatus_Deserialize;

/**  What the queue is doing. Mirrors `AiStatus` in src/library/api.ts. */
export type AiStatus_Deserialize = {
	state: AiState,
	/**  Captures described, or that could not be described. */
	done: number,
	/**  Captures that are not skipped. */
	total: number,
	/**  Why the provider failed, in the `error` state. */
	error?: string | null,
	/**  Who describes captures, so a failure can say whom to check. */
	provider: AiProvider,
	/**  The capture being described, in the `working` state. */
	current?: number | null,
};

/**  What the queue is doing. Mirrors `AiStatus` in src/library/api.ts. */
export type AiStatus_Serialize = {
	state: AiState,
	/**  Captures described, or that could not be described. */
	done: number,
	/**  Captures that are not skipped. */
	total: number,
	/**  Why the provider failed, in the `error` state. */
	error: string | null,
	/**  Who describes captures, so a failure can say whom to check. */
	provider: AiProvider,
	/**  The capture being described, in the `working` state. */
	current: number | null,
};

/**
 *  What Annotate with AI found. Mirrors `AnnotateOutcome` in
 *  src/editor/aiAnnotate.ts.
 */
export type AnnotateOutcome =
/**
 *  No provider is set up: the editor offers Settings, keeping the
 *  instruction.
 */
{ state: "needsProvider" } |
/**  The model's shapes that could be placed, and how many could not. */
{ state: "suggested"; suggestions: Suggestion[]; skipped: number; by: string };

/**
 *  Where the endpoint API key is kept. Mirrors `ApiKeyStorage` in
 *  src/settings/api.ts.
 */
export type ApiKeyStorage =
/**  The OS credential store (see `keychain.rs`); settings.json has no key. */
"keychain" |
/**  settings.json, because this system has no credential store that works. */
"settingsFile";

/**  How Grab-it looks. Mirrors `Appearance` in src/settings/api.ts. */
