/**
 *  A camera the webview listed by name. Mirrors `Camera` in
 *  src/settings/api.ts.
 */
export type Camera = {
	/**  The webview's `deviceId`, as `RecordingSettings::camera` saves it. */
	id: string,
	name: string,
};

/**  What the user asked to capture. */
export type CaptureMode = "region" | "window" |
/**  Every monitor, stitched into one image. */
"screen" |
/**  A single monitor. */
"monitor";

/**
 *  A capture's pointer as `meta.json` keeps it. Mirrors `CapturedPointer`
 *  in src/editor/api.ts.
 */
export type CapturedPointer = {
	/**  Where the hot spot is, in the saved image's pixels. */
	x: number,
	y: number,
	/**  The pixel that points, from the pointer image's top-left corner. */
	hotX: number,
	hotY: number,
	/**  The pointer image's size in pixels. */
	width: number,
	height: number,
	/**  The pointer image as a base64 PNG. */
	image: string,
};

/**
 *  What one version brought, as `latest.json` lists it. Mirrors
 *  `UpdateChanges` in the frontend.
 */
export type Changes = Changes_Serialize | Changes_Deserialize;

/**
 *  What one version brought, as `latest.json` lists it. Mirrors
 *  `UpdateChanges` in the frontend.
 */
export type Changes_Deserialize = {
	version: string,
	items?: string[],
};

/**
 *  What one version brought, as `latest.json` lists it. Mirrors
 *  `UpdateChanges` in the frontend.
 */
export type Changes_Serialize = {
	version: string,
	items: string[],
};

/**
 *  What an All-in-one overlay's toolbar chose, sent with its selection.
 *  An overlay opened for one mode has no toolbar, and this is ignored.
 */
export type Choice = Choice_Serialize | Choice_Deserialize;

/**
 *  What an All-in-one overlay's toolbar chose, sent with its selection.
 *  An overlay opened for one mode has no toolbar, and this is ignored.
 */
export type Choice_Deserialize = {
	intent?: Intent | null,
	mode?: CaptureMode | null,
	/**
	 *  The Timer: how long to wait, with the overlay closed, before the
	 *  chosen area is captured as it looks then.
	 */
	delaySeconds?: number | null,
	/**  Scroll: the user scrolls by hand instead of Grab-it scrolling. */
	scrollByHand?: boolean | null,
};

/**
 *  What an All-in-one overlay's toolbar chose, sent with its selection.
 *  An overlay opened for one mode has no toolbar, and this is ignored.
 */
export type Choice_Serialize = {
	intent: Intent | null,
	mode: CaptureMode | null,
	/**
	 *  The Timer: how long to wait, with the overlay closed, before the
	 *  chosen area is captured as it looks then.
	 */
	delaySeconds: number | null,
	/**  Scroll: the user scrolls by hand instead of Grab-it scrolling. */
	scrollByHand?: boolean,
};

/**  What a cleanup removed. Mirrors `Cleaned` in src/library/api.ts. */
export type Cleaned = {
	count: number,
	bytes: number,
};

/**  One code found in an image. Mirrors `QuickCode` in src/quick/api.ts. */
export type Code = {
	/**  The code's format as people call it, such as "QR code". */
	format: string,
	/**  What the code holds. */
	value: string,
	/**  Whether `value` is an http(s) link, which the card offers to open. */
	isLink: boolean,
};

/**  A point in a page's CSS pixels. Mirrors `Point` in src/overlay/geometry.ts. */
export type CssPoint = {
	x: number | null,
	y: number | null,
};

/**  A rectangle in CSS pixels of an overlay window, as the frontend sends it. */
export type CssRect = {
	x: number | null,
	y: number | null,
	width: number | null,
	height: number | null,
};

/**
 *  The pointer's smoothed path: a point a frame, as fractions of the frame,
 *  held inside it. Mirrors `CursorPath` in src/recording/zooms.ts.
 */
export type CursorPath = {
	fps: number,
	points: ([(number | null), (number | null)])[],
};

/**  Space on a disk, in bytes. Mirrors `DiskSpace` in src/library/api.ts. */
export type DiskSpace = {
	/**  What Grab-it may still write. */
	free: number,
	total: number,
};

/**  Mirrors `EditorInfo` in src/editor/api.ts. */
export type EditorInfo = EditorInfo_Serialize | EditorInfo_Deserialize;

/**  Mirrors `EditorInfo` in src/editor/api.ts. */
export type EditorInfo_Deserialize = {
	path: string,
	fileName: string,
	/**  The saved sidecar, or `None` when the capture has no annotations yet. */
	annotations?: Value | null,
	/**
	 *  The capture's pixels per point, from its `meta.json`; `None` for
	 *  captures saved before it was recorded (the editor then uses its own
	 *  window's density).
	 */
	scaleFactor?: number | null,
	/**
	 *  The mouse pointer saved with the capture, from its `meta.json`;
	 *  `None` when there was none.
	 */
	pointer?: CapturedPointer | null,
};

/**  Mirrors `EditorInfo` in src/editor/api.ts. */
export type EditorInfo_Serialize = {
	path: string,
	fileName: string,
	/**  The saved sidecar, or `None` when the capture has no annotations yet. */
	annotations: Value | null,
	/**
	 *  The capture's pixels per point, from its `meta.json`; `None` for
	 *  captures saved before it was recorded (the editor then uses its own
	 *  window's density).
	 */
	scaleFactor: number | null,
	/**
	 *  The mouse pointer saved with the capture, from its `meta.json`;
	 *  `None` when there was none.
	 */
	pointer: CapturedPointer | null,
};

/**
 *  The annotation editor's remembered choices, saved as they change and
 *  restored when it opens. Every key is optional: the editor uses its own
 *  default for anything missing, and checks each value it reads.
 */
export type EditorPreferences = EditorPreferences_Serialize | EditorPreferences_Deserialize;

/**
 *  The annotation editor's remembered choices, saved as they change and
 *  restored when it opens. Every key is optional: the editor uses its own
 *  default for anything missing, and checks each value it reads.
 */
export type EditorPreferences_Deserialize = {
	/**  The drawing colour, as `#rrggbb`. */
	color?: string | null,
	/**  The last tool picked, by its frontend name (`arrow`, `rect`…). */
	tool?: string | null,
	/**
	 *  Each tool's own width in pixels: the stroke width, or the font size
	 *  for text and the badge size for steps.
	 */
	widths?: { [key in string]: number },
	/**  Rectangles and ellipses are filled. */
	fill?: boolean | null,
	/**  Text sits on a coloured pill. */
	textBackground?: boolean | null,
	/**
	 *  How text without a pill is drawn: `outline` or `shadow`, by the
	 *  frontend's `TextStyle`; absent for plain text. Ignored while
	 *  `text_background` is on.
	 */
	textStyle?: string | null,
	/**  `pixelate` or `blur`. */
	blurMode?: string | null,
	/**
	 *  The stamp the Stamp tool places: a bundled stamp's name, or
	 *  `keycap:<label>` for a keycap preset.
	 */
	stamp?: string | null,
	/**
	 *  The last backdrop picked, as the editor writes it in a sidecar. Kept
	 *  as JSON: the editor checks each field when it reads it back.
	 */
	backdrop?: Value | null,
	/**
	 *  Frame captures that have no annotations yet with `backdrop`. Set
	 *  from the Settings window; the editor's own saves keep it.
	 */
	autoBackdrop?: boolean | null,
	/**
	 *  New captures start with their mouse pointer shown in the editor and
	 *  drawn into the copy made at capture time. Set from the Settings
	 *  window; the editor's own saves keep it. Off when unset.
	 */
	showPointer?: boolean | null,
	/**
	 *  Backdrops saved by name in the editor's backdrop panel. Set with
	 *  [`SettingsStore::set_backdrop_presets`]; the editor's other saves
	 *  keep them.
	 */
	backdropPresets?: BackdropPreset[],
	/**
	 *  Colours saved beside the built-in swatches, as `#rrggbb`, oldest
	 *  first. Set with [`SettingsStore::set_favorite_colors`]; the editor's
	 *  other saves keep them.
	 */
	favoriteColors?: string[],
};

